if(key==='shadows'){const list=[['Vesper','Guerreiro','COMUM',25],['Nyra','Arqueira','RARO',19],['Bront','Tanque','ÉPICO',42],['Cinder','Assassino','RARO',31],['Aster','Mago','LENDÁRIO',37],['Morrow','Cavaleiro','ÉPICO',48],['Umbra','General','MÍTICO',65]];html=`<p style="font-size:11px;color:#929ba9">Sombras desbloqueadas: ${state.shadows.length}. Limite atual ${shadowLimit()} aliados. Derrote elites e chefes para extrair novas sombras.</p>`+list.map((s,i)=>{const unlocked=state.shadows.includes(s[0]),sel=state.selectedShadows.includes(s[0]);return `<div class="item-card"><div><div class="item-name">♟ ${s[0]} <span class="rarity">${s[2]}</span></div><small>${s[1]} · NÍVEL ${state.level} · ATQ ${s[3]+state.level*2}</small></div>${unlocked?`<button data-shadow="${s[0]}">${sel?'REMOVER':'SELECIONAR'}</button>`:`<button disabled>${i===0?'DESBLOQUEADA':'BLOQUEADA'}</button>`}</div>`}).join('')+`<button id="shadow-train" class="item-card" style="width:100%;justify-content:center">TREINAR EXÉRCITO · 35 ✦</button>`;}
