content.innerHTML=html;panel.classList.remove('hidden');$('#close-panel').onclick=()=>panel.classList.add('hidden');content.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>equip(b.dataset.equip));content.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>{currentChapter=+b.dataset.chapter;panel.classList.add('hidden');startGame('campaign')});content.querySelectorAll('[data-shadow]').forEach(b=>b.onclick=()=>{const name=b.dataset.shadow;if(state.selectedShadows.includes(name))state.selectedShadows=state.selectedShadows.filter(x=>x!==name);else if(state.selectedShadows.length<shadowLimit())state.selectedShadows.push(name);else return toast('Limite de sombras atingido.');save();showPanel('shadows')});content.querySelectorAll('[data-talent]').forEach(b=>b.onclick=()=>{const k=b.dataset.talent;if(state.level-1<=Object.values(state.talents).reduce((a,b)=>a+b,0))return toast('Sem pontos de talento.');state.talents[k]++;save();showPanel('talents')});$('#upgrade-equipment')?.addEventListener('click',()=>{const cost=50+state.level*10;if(state.gold<cost)return toast('Fragmentos insuficientes.');state.gold-=cost;state.level++;save();toast('Equipamento aprimorado! Nível permanente +1');showPanel('equipment')});$('#shadow-train')?.addEventListener('click',()=>{if(state.gold<35)return toast('Fragmentos insuficientes.');state.gold-=35;state.selectedShadows.forEach(()=>{});save();toast('Seu exército treinou. Dano de sombras aumentado.');showPanel('shadows')});$('#duration-setting')?.addEventListener('input',e=>{state.settings.duration=+e.target.value;e.target.previousElementSibling.textContent=`${Math.round(+e.target.value/60)} MIN`;save()});$('#quality-toggle')?.addEventListener('click',()=>{state.settings.quality=state.settings.quality==='MÉDIA'?'BAIXA':'MÉDIA';save();showPanel('settings')});$('#sound-setting')?.addEventListener('click',()=>{state.settings.sound=!state.settings.sound;save();showPanel('settings')});$('#claim-mission')?.addEventListener('click',()