function bonusText(b){return Object.entries(b).map(([k,v])=>`+${v} ${({attack:'ATQ',defense:'DEF',hp:'VIDA',magic:'MAG',speed:'VEL',crit:'CRIT',shadow:'SOMBRA',cooldown:'RECARGA'})[k]||k}`).join(' · ')}
function baseAttack(){return Math.round(24*(1+(state.talents.power||0)*.05)+Object.values(state.equipped).reduce((a,n)=>a+(equipment.find(x=>x.name===n)?.bonus.attack||0),0))}
function combatPower(){return (1200+state.level*37+Object.keys(state.equipped).length*90+state.selectedShadows.length*115).toLocaleString('pt-BR')}
function shadowLimit(){return Math.min(4,1+Math.floor((state.level-1)/5))}
function equip(name){const it=equipment.find(x=>x.name===name)||state.inventory.find(x=>x.name===name);if(!it)return;state.equipped[it.slot]=name;save();showPanel('equipment');updateHome()}
function updateHome(){$('#home-level').textContent=String(state.level).padStart(2,'0');$('#home-portals').innerHTML=`${String(state.portals).padStart(2,'0')} <i>/ 10</i>`;$('#home-power').textContent=combatPower()}
function addEnemy(type='stalker',isBoss=false){let e=enemyPool.pop()||{};const angle=rand(0,Math.PI*2),distEdge=Math.max(W,H)*.63+45;e.x=player.x+Math.cos(angle)*distEdge;e.y=player.y+Math.sin(angle)*distEdge;e.type=type;e.boss=isBoss;e.r=isBoss?40: type==='brute'?18:type==='ranged'?12:type==='swift'?10:13;e.hp=isBoss?500+currentChapter*160: (type==='brute'?80:type==='ranged'?30:type==='swift'?22:38)+elapsed*.15;e.maxHp=e.hp;e.speed=isBoss?42:type==='brute'?36:type==='swift'?86:type==='ranged'?28:49;e.damage=isBoss?18:type==='brute'?13:7;e.attackTimer=rand(.2,1.7);e.phase=rand(0,6);e.flash=0;e.elite=false;enemies.push(e);return e}
function releaseEnemy(e){const i=enemies.indexOf(e);if(i>=0)enemies.splice(i,1);enemyPool.push(e)}
function emit(x,y,color,n=8){for(let i=0;i<n;i++){let p=particlePool.pop()||{};p.x=x;p.y=y;p.vx=rand(-100,100);p.vy=rand(-100,100);p.life=p.max=rand(.25,.65);p.color=color;p.r=rand(1,3);particles.push(p)}}
function startGame(mode='campaign'){gameMode=mode;$('#panel').classList.add('hidden');$('#pause-modal').classList.add('hidden');$('#result-modal').classList.add('hidden');setScreen('game');elapsed=0;spawnClock=0;attackClock=0;skillClock=0;runLevel=1;runXp=0;runNext=22;runKills=0;paused=false;boss=null;enemies=[];loot=[];particles=[];shadows=[];player={x:0,y:0,r:13,hp:100+(state.talents.vitality||0)*8,maxHp:100+(state.talents.vitality||0)*8,invuln:0,speed:210+(Object.values(state.equipped).reduce((a,n)=>a+(equipment.find(x=>x.name===n)?.bonus.speed||0),0)),attack:baseAttack()};for(let i=0;i<Math.min(state.selectedShadows.length,shadowLimit());i++)shadows.push({name:state.selectedShadows[i],angle:i*2.1,attack:0});$('#skill-hud').innerHTML='';for(let i=0;i<10;i++){let s=skillDefs[i];let el=document.createElement('div');el.className='skill-icon';el.innerHTML=`${s[2]}<small>${s[0].split(' ')[0]}</small>`;$('#skill-hud').append(el)}$('#boss-bar').classList.add('hidden');$('#level-toast').classList.add('hidden');$('#hud-level').textContent='NÍVEL 1';$('#kills').textContent='0';$('#timer').textContent='00:00';$('#hp-fill').style.width='100%';$('#xp-fill').style.width='0%';last=performance.now();requestAnimationFrame(loop)}
function spawnBoss(){if(boss)return;const e=addEnemy('brute',true);boss=e;$('#boss-bar').classList.remove('hidden');toast('UM GUARDIÃO ATRAVESSOU O PORTAL')}
function getNearest(max=1000){let best=null,bd=max;for(const e of enemies){const d=dist(e,player);if(d<bd){bd=d;best=e}}return best}
function killEnemy(e){const isBoss=e.boss;emit(e.x,e.y,isBoss?'#ff7186':'#72e5e9',isBoss?38:9);if(Math.random()<.75||isBoss)loot.push({x:e.x,y:e.y,value:isBoss?runNext*3:Math.ceil(3+elapsed/25),r:isBoss?7:4});if(Math.random()<.018&&!isBoss){const names=['Nyra','Bront','Cinder','Aster','Morrow','Umbra'];const next=names.find(n=>!state.shadows.includes(n));if(next){state.shadows.push(next);toast(`SOMBRA EXTRAÍDA: ${next.toUpperCase()}`)}}runKills++;state.kills++;$('#kills').textContent=runKills;releaseEnemy(e);if(isBoss){boss=null;$('#boss-bar').classList.add('hidden');finishRun(true)}}
function gainXp(v){runXp+=v;while(runXp>=runNext){runXp-=runNext;runLevel++;runNext=Math.floor(runNext*1.24+8);showLevelChoice()}}
function showLevelChoice(){paused=true;$('#toast').classList.add('hidden');$('#toast-level').textContent=String(runLevel).padStart(2,'0');$('#level-toast').classList.remove('hidden');setTimeout(()=>$('#level-toast').classList.add('hidden'),1300);$('#hud-level').textContent=`NÍVEL ${runLevel}`;const pool=skillDefs.map((s,i)=>({name:s[0],icon:s[2],desc:s[1],type:'skill',id:i}));pool.push({name:'Vigor renovado',icon:'♥',desc:'Recupere 35% da vida e aumente vida máxima em 12.',type:'hp'},{name:'Foco letal',icon:'⚔',desc:'Ataques causam 18% mais dano nesta incursão.',type:'damage'},{name:'Passos do Véu',icon:'➤',desc:'Movimento 15% mais rápido nesta incursão.',type:'speed'},{name:'Exército crescente',icon:'♟',desc:'Sua sombra ganha 30% de velocidade de ataque.',type:'shadow'});const picks=[];while(picks.length<3){const p=pool[Math.floor(Math.random()*pool.length)];if(!picks.includes(p))picks.push(p)}$('#upgrade-list').innerHTML=picks.map((p,i)=>`<button class="upgrade-card" data-upgrade="${i}"><span class="upgrade-icon">${p.icon}</span><h3>${p.name}</h3><p>${p.desc}</p></button>`).join('');upgradeDeck=picks;$('#level-modal').classList.remove('hidden');$('#upgrade-list').querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>chooseUpgrade(upgradeDeck[+b.dataset.upgrade]))}
let runSkills={},runDamage=1,runSpeed=1;
function chooseUpgrade(u){if(u.type==='skill')runSkills[u.id]=(runSkills[u.id]||0)+1;else if(u.type==='hp'){player.maxHp+=12;player.hp=Math.min(player.maxHp,player.hp+player.maxHp*.35)}else if(u.type==='damage')runDamage*=1.18;else if(u.type==='speed')runSpeed*=1.15;else if(u.type==='shadow')shadows.forEach(s=>s.attack*=.7);$('#level-modal').classList.add('hidden');paused=false;save()}
function finishRun(won){if(screen!=='game')return;paused=true;$('#level-modal').classList.add('hidden');$('#pause-modal').classList.add('hidden');$('#result-modal').classList.remove('hidden');const title=$('#result-title'),copy=$('#result-copy');if(won){title.textContent='Portal selado.';$('#result-kicker').textContent='VITÓRIA · CHEFE DERROTADO';copy.textContent=`O Guardião caiu. A próxima trilha se abre para você.`;const reward=40+currentChapter*20+runLevel*3;state.gold+=reward;state.portals=Math.max(state.portals,currentChapter+1);state.unlocked=Math.max(state.unlocked,Math.min(9,currentChapter+1));$('#result-rewards').innerHTML=`<div><strong>+${reward}</strong><small>FRAGMENTOS</small></div><div><strong>+${runLevel}</strong><small>NÍVEIS DE CAÇADA</small></div><div><strong>${runKills}</strong><small>ELIMINAÇÕES</small></div>`}else{$('#result-kicker').textContent='CAÇADA ENCERRADA';title.textContent='A noite cobra seu preço.';copy.textContent='Você caiu em combate, mas sua experiência permanente foi preservada.';const reward=Math.floor(runKills*.35);state.gold+=reward;$('#result-rewards').innerHTML=`<div><strong>+${reward}</strong><small>FRAGMENTOS</small></div><div><strong>${runKills}</strong><small>ELIMINAÇÕES</small></div>`}state.xp+=runLevel*4;state.level=Math.max(state.level,Math.floor(state.xp/100)+1);save();$('#result-continue').onclick=()=>{ $('#result-modal').classList.add('hidden');setScreen('home');updateHome()}}

function update(dt){if(paused||screen!=='game')return;elapsed+=dt;spawnClock+=dt;attackClock+=dt;skillClock+=dt;player.invuln=Math.max(0,player.invuln-dt);const dx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+moveTouch.x,dy=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0)+moveTouch.y,len=Math.hypot(dx,dy)||1;player.x+=dx/len*player.speed*runSpeed*dt;player.y+=dy/len*player.speed*runSpeed*dt;
const maxEnemies=state.settings.quality==='BAIXA'?38:72;if(spawnClock>.85&&enemies.length<maxEnemies){spawnClock=0;const kinds=['stalker','stalker','swift','brute','ranged'];addEnemy(kinds[Math.floor(Math.random()*kinds.length)]);if(elapsed>25&&Math.random()<.3)addEnemy('stalker')}
if(elapsed>=state.settings.duration&&!boss)spawnBoss();
for(const e of [...enemies]){e.phase+=dt;e.flash=Math.max(0,e.flash-dt);e.attackTimer-=dt;let vx=player.x-e.x,vy=player.y-e.y,d=Math.hypot(vx,vy)||1;if(e.type==='ranged'&&!e.boss){if(d>220){e.x+=vx/d*e.speed*dt;e.y+=vy/d*e.speed*dt}else if(d<145){e.x-=vx/d*e.speed*dt;e.y-=vy/d*e.speed*dt}if(e.attackTimer<=0&&d<320){e.attackTimer=2.1;loot.push({x:e.x,y:e.y,value:0,hostile:true,targetX:player.x,targetY:player.y,life:1.1})}}else{let sp=e.speed*(e.boss&&e.hp<e.maxHp*.5?1.35:1);e.x+=vx/d*sp*dt;e.y+=vy/d*sp*dt}
if(d<e.r+player.r&&e.attackTimer<=0){e.attackTimer=e.boss?1.25:.85;if(player.invuln<=0){const def=Object.values(state.equipped).reduce((a,n)=>a+(equipment.find(x=>x.name===n)?.bonus.defense||0),0);player.hp-=Math.max(3,e.damage-def*.35);player.invuln=.28;emit(player.x,player.y,'#ff7381',5);if(player.hp<=0){player.hp=0;finishRun(false)}}}}
if(attackClock>.78){attackClock=0;const target=getNearest(480);if(target){const dmg=(player.attack+runLevel*1.6)*runDamage*(1+(runSkills[0]||0)*.32);target.hp-=dmg;target.flash=.12;emit(target.x,target.y,'#80e8f4',4);if(target.hp<=0)killEnemy(target)}}
for(let i=0;i<skillDefs.length;i++){if(!runSkills[i])continue;const level=runSkills[i],def=skillDefs[i],interval=Math.max(1.3,def[4]/2.4-level*.28);if(!runSkills[`${i}cool`])runSkills[`${i}cool`]=rand(.4,interval);runSkills[`${i}cool`]-=dt;if(runSkills[`${i}cool`]<=0){runSkills[`${i}cool`]=interval;const radius=def[3]==='attack'?115:330;let targets=enemies.filter(e=>dist(e,player)<radius).sort((a,b)=>dist(a,player)-dist(b,player)).slice(0,Math.max(1,Math.min(8,2+level*2)));if(i===5){player.invuln=Math.max(player.invuln,1.3);emit(player.x,player.y,'#77c5ff',18)}else if(i===9){player.hp=Math.min(player.maxHp,player.hp+3+level);emit(player.x,player.y,'#80ffc5',9)}else{for(const t of targets){t.hp-=player.attack*(.75+level*.5);t.flash=.12;emit(t.x,t.y,i%2?'#9b74ff':'#72e5e9',7);if(t.hp<=0)killEnemy(t)}emit(player.x,player.y,i%2?'#9b74ff':'#72e5e9',10)}}}
for(const s of shadows){s.angle+=dt*.8;s.attack-=dt;const sx=player.x+Math.cos(s.angle)*42,sy=player.y+Math.sin(s.angle)*30;const target=getNearest(260);if(target&&s.attack<=0){s.attack=.95;target.hp-=(18+state.level*2)*(1+Object.values(state.equipped).reduce((a,n)=>a+(equipment.find(x=>x.name===n)?.bonus.shadow||0),0)/100);emit(target.x,target.y,'#a282ff',4);if(target.hp<=0)killEnemy(target)}}
for(const l of [...loot]){if(l.hostile){l.x+=(l.targetX-l.x)*dt*2.2;l.y+=(l.targetY-l.y)*dt*2.2;l.life-=dt;if(l.life<=0){loot.splice(loot.indexOf(l),1);if(player.invuln<=0){player.hp-=7;player.invuln=.25}}continue}const d=dist(l,player);if(d<180){l.x+=(player.x-l.x)*dt*(d<35?8:3.2);l.y+=(player.y-l.y)*dt*(d<35?8:3.2)}if(d<player.r+10){loot.splice(loot.indexOf(l),1);gainXp(l.value);if(l.value>0)emit(player.x,player.y,'#72e5e9',3)}}
for(const p of [...particles]){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0){particles.splice(particles.indexOf(p),1);particlePool.push(p)}}$('#hp-fill').style.width=`${100*player.hp/player.maxHp}%`;$('#xp-fill').style.width=`${100*runXp/runNext}%`;if(boss){const pct=clamp(boss.hp/boss.maxHp,0,1);$('#boss-fill').style.width=`${pct*100}%`,$('#boss-hp-label').textContent=`${Math.ceil(pct*100)}%`;if(boss.hp<=0)killEnemy(boss)}const sec=Math.floor(elapsed);$('#timer').textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`}
function draw(){if(screen!=='game')return;ctx.clearRect(0,0,W,H);const camx=player.x-W/2,camy=player.y-H/2;ctx.fillStyle='#101319';ctx.fillRect(0,0,W,H);
