const itemPool=[{name:'Lâmina do Errante',slot:'Arma',rarity:'Comum',bonus:{attack:5},desc:'+5 de ataque'},{name:'Adaga do Crepúsculo',slot:'Arma',rarity:'Raro',bonus:{attack:11,shadow:4},desc:'+11 ataque · +4% sombras'},{name:'Manto do Vigia',slot:'Armadura',rarity:'Comum',bonus:{defense:4},desc:'+4 de defesa'},{name:'Couraça do Véu',slot:'Armadura',rarity:'Épico',bonus:{defense:10,hp:25},desc:'+10 defesa · +25 vida'},{name:'Anel de Cinzas',slot:'Relíquia',rarity:'Raro',bonus:{attack:4,hp:12},desc:'+4 ataque · +12 vida'},{name:'Selo Umbral',slot:'Relíquia',rarity:'Épico',bonus:{shadow:12,defense:3},desc:'+12% sombras · +3 defesa'}];
