let state=loadState(),screen='home',paused=false,player=null,enemies=[],loot=[],particles=[],particlePool=[],shadows=[],keys={},moveTouch={x:0,y:0},joystickActive=false,elapsed=0,spawnClock=0,attackClock=0,runXp=0,runNext=45,runLevel=1,runSkills=[],runDamage=1,runSpeed=1,boss=null,last=0,W=0,H=0,ctx,currentChapter=1,runMode='campaign',finished=false,toastTimer,levelToastTimer,dragX=null,heroRotation=0,killsThisRun=0;
function loadState(){try{const raw=JSON.parse(localStorage.getItem(STORAGE)||'null');if(!raw)return structuredClone(defaultState);return {...structuredClone(defaultState),...raw,settings:{...defaultState.settings,...raw.settings},equipped:{...defaultState.equipped,...raw.equipped},talents:{...defaultState.talents,...raw.talents},quests:{...defaultState.quests,...raw.quests}}}catch{return structuredClone(defaultState)}}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));$('#save-status').textContent='PROGRESSO SALVO'}catch{$('#save-status').textContent='SALVAMENTO INDISPONÍVEL'}}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.add('hidden'),2300)}
function updateHome(){$('#home-level').textContent=String(state.level).padStart(2,'0');$('#home-portals').innerHTML=`${String(state.portals).padStart(2,'0')} <i>/ 10</i>`;$('#home-power').textContent=(1240+state.level*45+state.portals*110).toLocaleString('pt-BR')}
function showPanel(name){const titles={character:'Personagem',equipment:'Equipamentos',shadows:'Exército de sombras',campaign:'Campanha',talents:'Talentos',settings:'Ajustes',inventory:'Inventário',quests:'Missões'};$('#panel-title').textContent=titles[name]||'Registro';$('#panel-content').innerHTML=panelMarkup(name);$('#panel').classList.remove('hidden');wirePanel(name)}
function panelMarkup(name){if(name==='character')return `<div class="panel-grid"><article class="data-card"><small>NÍVEL DO CAÇADOR</small><strong>${state.level}</strong><p>${state.xp} / ${state.xpNext} XP</p></article><article class="data-card"><small>ATAQUE</small><strong>${getStats().attack}</strong><p>Base + equipamento + talento</p></article><article class="data-card"><small>VIDA MÁXIMA</small><strong>${getStats().hp}</strong><p>Defesa ${getStats().defense}</p></article><article class="data-card"><small>PORTAIS SELADOS</small><strong>${state.portals} / 10</strong><p>${state.kills} eliminações totais</p></article></div><h3>Registro de combate</h3><p>O poder de Nox cresce ao completar portais, coletar experiência e aprimorar talentos.</p><button class="primary-btn" data-open="quests">VER MISSÕES <b>→</b></button>`;
if(name==='equipment'||name==='inventory'){const names=[...new Set([...state.inventory,...Object.values(state.equipped).filter(Boolean)])];return `<div class="equipment-slots">${Object.entries(state.equipped).map(([slot,item])=>`<div class="item-card"><small>${slot.toUpperCase()}</small><strong>${item||'Vazio'}</strong><span>Equipado</span></div>`).join('')}</div><h3>${name==='inventory'?'Inventário':'Itens disponíveis'}</h3><div class="panel-grid">${names.length?names.map(n=>{const it=itemPool.find(x=>x.name===n);return it?`<article class="item-card"><span class="rarity ${it.rarity.toLowerCase()}">${it.rarity}</span><strong class="item-name">${it.name}</strong><small>${it.slot} · ${it.desc}</small><button class="text-btn" data-equip="${it.name}">${state.equipped[it.slot]===it.name?'EQUIPADO':'EQUIPAR'} →</button></article>`:''}).join(''):'<p>Seu inventário está vazio. Derrote o guardião para encontrar equipamentos.</p>'}</div>`}
if(name==='shadows')return `<div class="panel-grid">${[{name:'Sentinela',cost:3,desc:'Ataca automaticamente inimigos próximos.'},{name:'Lâmina Errante',cost:5,desc:'Um espírito veloz que reforça seu exército.'},{name:'Vigia do Véu',cost:8,desc:'Uma sombra veterana de grande poder.'}].map((s,i)=>`<article class="shadow-card"><span>✦ ${state.shadows.includes(s.name)?'RECRUTADO':'SOMBRA '+(i+1)}</span><strong>${s.name}</strong><p>${s.desc}</p><button class="text-btn" data-shadow="${s.name}" data-cost="${s.cost}">${state.shadows.includes(s.name)?'NO EXÉRCITO':`RECRUTAR · ${s.cost} FRAGMENTOS`}</button></article>`).join('')}</div><p>Fragmentos umbrais: <b>${state.shards}</b> · Recrutas acompanham você em combate.</p>`;
if(name==='campaign')return `<div class="chapter-list">${Array.from({length:10},(_,i)=>{const n=i+1,open=n<=state.unlocked;return `<article class="chapter-card ${open?'':'locked'}"><small>CAPÍTULO ${String(n).padStart(2,'0')}</small><strong>${['Primeiro Portal','Ecos da Cripta','Bosque Sem Sol','Fortaleza Partida','Mar de Cinzas','Catedral Vazia','Trono Esquecido','Abismo Rubro','Último Véu','Ascensão'][i]}</strong><p>${open?'Portal disponível · Guardião ao final':'Conclua o capítulo anterior para desbloquear'}</p><button class="text-btn" data-chapter="${n}" ${open?'':'disabled'}>${open?'ENTRAR NO PORTAL →':'BLOQUEADO'}</button></article>`}).join('')}</div>`;
if(name==='talents'){const defs=[['might','Poder','Aumenta o ataque permanente.'],['ward','Proteção','Aumenta vida e defesa.'],['essence','Essência','Mais experiência por orbe.']];return `<p>Pontos disponíveis: <b>${state.level-1-Object.values(state.talents).reduce((a,b)=>a+b,0)}</b></p><div class="panel-grid">${defs.map(([k,label,desc])=>`<article class="data-card"><small>${label.toUpperCase()} · NÍVEL ${state.talents[k]}</small><strong>${desc}</strong><button class="text-btn" data-talent="${k}">APRIMORAR · 1 PONTO →</button></article>`).join('')}</div>`}
if(name==='quests')return `<div class="panel-grid">${[{id:'kills',name:'Controle da Horda',goal:25,value:state.quests.kills,reward:'50 ouro'},{id:'runs',name:'Caçador Persistente',goal:1,value:state.quests.runs,reward:'2 fragmentos'},{id:'bosses',name:'Caçador de Guardiões',goal:1,value:state.quests.bosses,reward:'100 ouro'}].map(q=>`<article class="data-card"><small>MISSÃO</small><strong>${q.name}</strong><p>${Math.min(q.goal,q.value)} / ${q.goal} · Recompensa: ${q.reward}</p><button class="text-btn" data-claim="${q.id}" ${q.value>=q.goal&&!state.quests.claimed.includes(q.id)?'':'disabled'}>${state.quests.claimed.includes(q.id)?'CONCLUÍDA':'RESGATAR →'}</button></article>`).join('')}</div>`;
if(name==='settings')return `<h3>Preferências de jogo</h3><div class="panel-grid"><article class="data-card"><small>DURAÇÃO DA CAÇADA</small><strong>${state.settings.duration} segundos</strong><button class="text-btn" data-duration>ALTERAR DURAÇÃO →</button></article><article class="data-card"><small>QUALIDADE VISUAL</small><strong>${state.settings.quality}</strong><button class="text-btn" data-quality>ALTERNAR QUALIDADE →</button></article><article class="data-card"><small>SOM</small><strong>${state.settings.sound?'Ligado':'Desligado'}</strong><button class="text-btn" data-sound>ALTERNAR SOM →</button></article><article class="data-card"><small>SALVAMENTO</small><strong>Local neste dispositivo</strong><p>O progresso é guardado automaticamente neste navegador.</p></article></div><button class="text-btn" data-reset>APAGAR PROGRESSO LOCAL</button>`;return '<p>Seção indisponível.</p>'}

