function wirePanel(name){$('#close-panel').onclick=()=>$('#panel').classList.add('hidden');$('#panel').onclick=e=>{if(e.target===$('#panel'))$('#panel').classList.add('hidden')};$('#panel-content').querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{const it=itemPool.find(x=>x.name===b.dataset.equip);state.equipped[it.slot]=it.name;save();showPanel(name)});$('#panel-content').querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>{if(+b.dataset.chapter<=state.unlocked){currentChapter=+b.dataset.chapter;$('#panel').classList.add('hidden');startGame('campaign')}});$('#panel-content').querySelectorAll('[data-shadow]').forEach(b=>b.onclick=()=>{const n=b.dataset.shadow,c=+b.dataset.cost;if(state.shadows.includes(n)){toast('Essa sombra já faz parte do exército.');return}if(state.shards<c){toast('Fragmentos insuficientes. Derrote guardiões para obtê-los.');return}state.shards-=c;state.shadows.push(n);save();showPanel('shadows');toast(`${n} se uniu ao exército.`)});$('#panel-content').querySelectorAll('[data-talent]').forEach(b=>b.onclick=()=>{const points=state.level-1-Object.values(state.talents).reduce((a,v)=>a+v,0);if(points<=0){toast('Você ainda não tem pontos de talento.');return}state.talents[b.dataset.talent]++;save();showPanel('talents')});$('#panel-content').querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>{const id=b.dataset.claim,q=state.quests;if(q.claimed.includes(id)||q[id]<(id==='kills'?25:1))return;q.claimed.push(id);if(id==='runs')state.shards+=2;else state.gold+=id==='kills'?50:100;save();showPanel('quests');toast('Recompensa resgatada!')});const d=$('[data-duration]');if(d)d.onclick=()=>{const vals=[60,90,120,180];state.settings.duration=vals[(vals.indexOf(state.settings.duration)+1)%vals.length];save();showPanel('settings')};const q=$('[data-quality]');if(q)q.onclick=()=>{state.settings.quality=state.settings.quality==='ALTA'?'BAIXA':'ALTA';save();showPanel('settings')};const s=$('[data-sound]');if(s)s.onclick=()=>{state.settings.sound=!state.settings.sound;save();showPanel('settings')};const reset=$('[data-reset]');if(reset)reset.onclick=()=>{if(confirm('Apagar todo o progresso salvo neste dispositivo?')){localStorage.removeItem(STORAGE);state=structuredClone(defaultState);save();updateHome();showPanel('settings')}};$('#panel-content').querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>showPanel(b.dataset.open))}
function getStats(){const eq=Object.values(state.equipped).map(n=>itemPool.find(x=>x.name===n)).filter(Boolean);return {attack:20+state.talents.might*4+eq.reduce((a,x)=>a+(x.bonus.attack||0),0),defense:state.talents.ward*2+eq.reduce((a,x)=>a+(x.bonus.defense||0),0),hp:100+state.talents.ward*8+eq.reduce((a,x)=>a+(x.bonus.hp||0),0),shadow:eq.reduce((a,x)=>a+(x.bonus.shadow||0),0)}}
function closeAll(){['panel','level-modal','pause-modal','result-modal'].forEach(id=>$('#'+id).classList.add('hidden'))}
function startGame(mode='campaign'){runMode=mode;finished=false;paused=false;elapsed=spawnClock=attackClock=0;runXp=0;runNext=45;runLevel=1;runSkills=[];runDamage=1;runSpeed=1;killsThisRun=0;enemies=[];loot=[];particles=[];shadows=state.shadows.map((n,i)=>({name:n,angle:i*Math.PI*2/Math.max(1,state.shadows.length),attack:rand(.1,.8)}));boss=null;const st=getStats();player={x:0,y:0,r:13,hp:st.hp,maxHp:st.hp,speed:210,attack:st.attack,invuln:0,dodgeCd:0};screen='game';$('#home-screen').classList.remove('active');$('#game-hud').classList.remove('hidden');$('#game').style.display='block';$('#boss-bar').classList.add('hidden');$('#level-modal').classList.add('hidden');$('#result-modal').classList.add('hidden');$('#pause-modal').classList.add('hidden');$('.stage-title small').textContent=`CAPÍTULO ${String(currentChapter).padStart(2,'0')} · FASE 01`;$('.stage-title b').textContent=['PRIMEIRO PORTAL','ECOS DA CRIPTA','BOSQUE SEM SOL','FORTALEZA PARTIDA','MAR DE CINZAS','CATEDRAL VAZIA','TRONO ESQUECIDO','ABISMO RUBRO','ÚLTIMO VÉU','ASCENSÃO'][currentChapter-1];$('#kills').textContent='0';$('#hud-level').textContent='NÍVEL 1';resize();last=performance.now();requestAnimationFrame(loop)}
function finishRun(won){if(finished)return;finished=true;paused=true;screen='result';$('#game-hud').classList.add('hidden');$('#result-modal').classList.remove('hidden');$('#result-kicker').textContent=won?'PORTAL SELADO':'CAÇADA ENCERRADA';$('#result-title').textContent=won?'Vitória.':'Recuo estratégico.';$('#result-copy').textContent=won?`O guardião do capítulo ${currentChapter} foi derrotado. A noite agora pertence a você.`:`Você eliminou ${killsThisRun} inimigos e alcançou o nível ${runLevel}. Reúna forças e tente novamente.`;const gold=won?80+currentChapter*15:Math.max(10,killsThisRun*2);state.gold+=gold;state.quests.runs++;state.quests.kills+=killsThisRun;if(won){state.portals=Math.max(state.portals,currentChapter);state.unlocked=Math.min(10,Math.max(state.unlocked,currentChapter+1));state.quests.bosses++;state.shards+=2;if(Math.random()<.75){const item=itemPool[Math.floor(Math.random()*itemPool.length)];if(!state.inventory.includes(item.name))state.inventory.push(item.name)}}save();$('#result-rewards').innerHTML=`<div class="data-card"><small>OURO</small><strong>+${gold}</strong></div><div class="data-card"><small>ELIMINAÇÕES</small><strong>${killsThisRun}</strong></div><div class="data-card"><small>FRAGMENTOS</small><strong>${won?'+2':'—'}</strong></div>`;$('#result-continue').onclick=()=>{closeAll();screen='home';$('#game').style.display='none';$('#home-screen').classList.add('active');updateHome()}}

