function addEnemy(type){const a=Math.random()*Math.PI*2,d=Math.max(W,H)*.65+60,hpScale=1+currentChapter*.18;const base={stalker:[34,17,7,12],swift:[25,26,6,9],brute:[100,10,16,19],ranged:[42,12,8,11]}[type]||[35,16,7,12];const e={type,x:player.x+Math.cos(a)*d,y:player.y+Math.sin(a)*d,hp:base[0]*hpScale,maxHp:base[0]*hpScale,speed:base[1]+currentChapter*.35,damage:base[2]+currentChapter*.7,r:base[3],phase:Math.random()*6,flash:0,attackTimer:rand(.2,1.3),boss:false};enemies.push(e);return e}
function spawnBoss(){if(boss)return;const a=Math.random()*Math.PI*2;boss={type:'boss',x:player.x+Math.cos(a)*Math.max(W,H)*.62,y:player.y+Math.sin(a)*Math.max(W,H)*.62,hp:1050+currentChapter*300,maxHp:1050+currentChapter*300,speed:35+currentChapter*1.5,damage:20+currentChapter*2,r:31,phase:0,flash:0,attackTimer:1,boss:true};enemies.push(boss);$('#boss-bar').classList.remove('hidden');toast('O Guardião do Véu surgiu!')}
function getNearest(range=1e9){let best=null,bd=range;for(const e of enemies){const d=dist(e,player);if(d<bd){bd=d;best=e}}return best}
function emit(x,y,color,count=5){for(let i=0;i<count;i++){const p=particlePool.pop()||{};p.x=x;p.y=y;p.vx=rand(-100,100);p.vy=rand(-100,100);p.life=p.max=rand(.25,.65);p.r=rand(1.3,3.8);p.color=color;particles.push(p)}}
function killEnemy(e){const i=enemies.indexOf(e);if(i<0)return;enemies.splice(i,1);killsThisRun++;state.kills++;$('#kills').textContent=killsThisRun;emit(e.x,e.y,e.boss?'#ff7189':'#a282ff',e.boss?30:9);if(e.boss){boss=null;finishRun(true);return}loot.push({x:e.x,y:e.y,value:rand(9,15)*(1+state.talents.essence*.12),r:5})}
function gainXp(v){runXp+=v;while(runXp>=runNext){runXp-=runNext;runLevel++;runNext=Math.round(runNext*1.27);paused=true;$('#toast-level').textContent=String(runLevel).padStart(2,'0');$('#level-toast').classList.remove('hidden');clearTimeout(levelToastTimer);levelToastTimer=setTimeout(()=>$('#level-toast').classList.add('hidden'),1800);showUpgrades()}}
function showUpgrades(){const choices=[];const available=skillDefs.map((_,i)=>i).sort(()=>Math.random()-.5);for(const i of available){if(choices.length===3)break;choices.push(i)}const cards=choices.map(i=>{const [name,desc,icon]=skillDefs[i],lv=runSkills[i]||0;return `<button class="upgrade-card" data-upgrade="${i}"><span class="upgrade-icon">${icon}</span><b>${lv?`APRIMORAMENTO · NÍVEL ${lv+1}`:'NOVA HABILIDADE'}</b><strong>${name}</strong><small>${desc}</small></button>`}).join('');$('#upgrade-list').innerHTML=`<button class="upgrade-card" data-heal><span class="upgrade-icon">♥</span><b>RECUPERAÇÃO</b><strong>Fôlego renovado</strong><small>Recupera 30% da vida máxima.</small></button>${cards}`;$('#level-modal').classList.remove('hidden');$('#upgrade-list').querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{const i=+b.dataset.upgrade;runSkills[i]=(runSkills[i]||0)+1;$('#level-modal').classList.add('hidden');paused=false;last=performance.now();requestAnimationFrame(loop);renderSkillHud()});$('[data-heal]').onclick=()=>{player.hp=Math.min(player.maxHp,player.hp+player.maxHp*.3);$('#level-modal').classList.add('hidden');paused=false;last=performance.now();requestAnimationFrame(loop)}}
function renderSkillHud(){const owned=runSkills.map((l,i)=>l?`<div class="skill-icon" title="${skillDefs[i][0]} · nível ${l}">${skillDefs[i][2]}<small>${l}</small></div>`:'').filter(Boolean).join('');$('#skill-hud').innerHTML=owned}
function update(dt){if(paused||screen!=='game')return;elapsed+=dt;spawnClock+=dt;attackClock+=dt;player.invuln=Math.max(0,player.invuln-dt);player.dodgeCd=Math.max(0,player.dodgeCd-dt);const dx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+moveTouch.x,dy=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0)+moveTouch.y,len=Math.hypot(dx,dy)||1;player.x+=dx/len*player.speed*runSpeed*dt;player.y+=dy/len*player.speed*runSpeed*dt;
const maxEnemies=state.settings.quality==='BAIXA'?38:72;if(spawnClock>.85&&enemies.length<maxEnemies&&!boss){spawnClock=0;const kinds=['stalker','stalker','swift','brute','ranged'];addEnemy(kinds[Math.floor(Math.random()*kinds.length)]);if(elapsed>25&&Math.random()<.3)addEnemy('stalker')}if(elapsed>=state.settings.duration&&!boss)spawnBoss();
for(const e of [...enemies]){e.phase+=dt;e.flash=Math.max(0,e.flash-dt);e.attackTimer-=dt;let vx=player.x-e.x,vy=player.y-e.y,d=Math.hypot(vx,vy)||1;if(e.type==='ranged'&&!e.boss){if(d>220){e.x+=vx/d*e.speed*dt;e.y+=vy/d*e.speed*dt}else if(d<145){e.x-=vx/d*e.speed*dt;e.y-=vy/d*e.speed*dt}if(e.attackTimer<=0&&d<320){e.attackTimer=2.1;loot.push({x:e.x,y:e.y,value:0,hostile:true,targetX:player.x,targetY:player.y,life:1.1,r:4})}}else{let sp=e.speed*(e.boss&&e.hp<e.maxHp*.5?1.35:1);e.x+=vx/d*sp*dt;e.y+=vy/d*sp*dt}if(d<e.r+player.r&&e.attackTimer<=0){e.attackTimer=e.boss?1.25:.85;if(player.invuln<=0){player.hp-=Math.max(3,e.damage-getStats().defense*.35);player.invuln=.45;emit(player.x,player.y,'#ff7381',5);if(player.hp<=0){player.hp=0;finishRun(false);return}}}}
if(attackClock>.78){attackClock=0;const target=getNearest(480);if(target){const dmg=(player.attack+runLevel*1.6)*runDamage*(1+(runSkills[0]||0)*.32);target.hp-=dmg;target.flash=.12;emit(target.x,target.y,'#80e8f4',4);if(target.hp<=0)killEnemy(target)}}
for(let i=0;i<skillDefs.length;i++){if(!runSkills[i])continue;const level=runSkills[i],def=skillDefs[i],key=`${i}_cool`,interval=Math.max(1.3,def[4]/2.4-level*.28);if(runSkills[key]==null)runSkills[key]=rand(.4,interval);runSkills[key]-=dt;if(runSkills[key]<=0){runSkills[key]=interval;const radius=def[3]==='attack'?115:330;let targets=enemies.filter(e=>dist(e,player)<radius).sort((a,b)=>dist(a,player)-dist(b,player)).slice(0,Math.max(1,Math.min(8,2+level*2)));if(i===5){player.invuln=Math.max(player.invuln,1.3);emit(player.x,player.y,'#77c5ff',18)}else if(i===9){player.hp=Math.min(player.maxHp,player.hp+3+level);emit(player.x,player.y,'#80ffc5',9)}else{for(const t of targets){t.hp-=player.attack*(.75+level*.5);t.flash=.12;emit(t.x,t.y,i%2?'#9b74ff':'#72e5e9',7);if(t.hp<=0)killEnemy(t)}emit(player.x,player.y,i%2?'#9b74ff':'#72e5e9',10)}}}
for(const s of shadows){s.angle+=dt*.8;s.attack-=dt;const target=getNearest(260);if(target&&s.attack<=0){s.attack=.95;target.hp-=(18+state.level*2)*(1+getStats().shadow/100);emit(target.x,target.y,'#a282ff',4);if(target.hp<=0)killEnemy(target)}}
for(const l of [...loot]){if(l.hostile){l.x+=(l.targetX-l.x)*dt*2.2;l.y+=(l.targetY-l.y)*dt*2.2;l.life-=dt;if(l.life<=0){loot.splice(loot.indexOf(l),1);if(player.invuln<=0){player.hp-=7;player.invuln=.25}}continue}const d=dist(l,player);if(d<180){l.x+=(player.x-l.x)*dt*(d<35?8:3.2);l.y+=(player.y-l.y)*dt*(d<35?8:3.2)}if(d<player.r+10){loot.splice(loot.indexOf(l),1);gainXp(l.value);if(l.value>0)emit(player.x,player.y,'#72e5e9',3)}}
for(const p of [...particles]){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0){particles.splice(particles.indexOf(p),1);particlePool.push(p)}}$('#hp-fill').style.width=`${100*player.hp/player.maxHp}%`;$('#xp-fill').style.width=`${100*runXp/runNext}%`;if(boss){const pct=clamp(boss.hp/boss.maxHp,0,1);$('#boss-fill').style.width=`${pct*100}%`;$('#boss-hp-label').textContent=`${Math.ceil(pct*100)}%`;if(boss.hp<=0)killEnemy(boss)}const sec=Math.floor(elapsed);$('#timer').textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`}

